sp_widget.client_script:
function($window) {

    var c = this;

    c.navigateTo = function(page) {

        var pageMap = {

            patients:
            '/trackmed_patients',

            caregivers:
            '/trackmed_caregivers',

            refill:
            '/trackmed_refill',

            alerts:
            '/trackmed_alerts'

        };

        if(pageMap[page]) {

            $window.location.href =
            pageMap[page];

        }

    };

}

sp_widget.css:
.quick-actions-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.quick-action-card {

  background: linear-gradient(
      135deg,
      #0a2463,
      #1a73e8
  );

  border-radius: 14px;

  padding: 20px;

  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;

  color: #fff;
  cursor: pointer;

  transition:
    transform 0.2s,
    box-shadow 0.2s;

  box-shadow:
    0 4px 14px
    rgba(26,115,232,0.3);
}

.quick-action-card:hover {

  transform: translateY(-4px);

  box-shadow:
    0 8px 28px
    rgba(26,115,232,0.5);
}

.quick-action-card i {
  font-size: 28px;
}

.quick-action-card span {
  font-size: 14px;
  font-weight: 600;
}

